import{_ as a,o as i,c as e,a3 as t}from"./chunks/framework.WFmvnizL.js";const c=JSON.parse('{"title":"如何进行数据迁移、备份恢复？","description":"按哪吒监控当前安装脚本说明 Dashboard 备份、迁移与恢复：区分 Docker、systemd 和 OpenRC 的启停命令，备份数据目录并验证恢复结果。","frontmatter":{"description":"按哪吒监控当前安装脚本说明 Dashboard 备份、迁移与恢复：区分 Docker、systemd 和 OpenRC 的启停命令，备份数据目录并验证恢复结果。","outline":"deep"},"headers":[],"relativePath":"guide/q5.md","filePath":"guide/q5.md","lastUpdated":1792674226000}'),h={name:"guide/q5.md"};function n(l,s,d,p,o,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="如何进行数据迁移、备份恢复" tabindex="-1">如何进行数据迁移、备份恢复？ <a class="header-anchor" href="#如何进行数据迁移、备份恢复" aria-label="Permalink to &quot;如何进行数据迁移、备份恢复？&quot;">​</a></h1><p><strong>先停止 Dashboard，再备份；恢复完成后，使用对应部署方式的命令启动。</strong> 当前一键脚本没有单独的“停止面板”和“启动面板”菜单。</p><p>脚本中的“重启并更新面板”会拉取镜像或下载最新版程序，<strong>不是单纯重启</strong>。备份恢复时不要用它代替下文的启停命令，也不要使用会删除面板目录的“卸载管理面板”。</p><h2 id="_1-确认部署方式和备份范围" tabindex="-1">1. 确认部署方式和备份范围 <a class="header-anchor" href="#_1-确认部署方式和备份范围" aria-label="Permalink to &quot;1. 确认部署方式和备份范围&quot;">​</a></h2><p>当前脚本支持 Docker 和独立安装，默认面板目录为 <code>/opt/nezha/dashboard</code>：</p><ul><li><strong>Docker：</strong> 使用该目录下的 <code>docker-compose.yaml</code>，服务名为 <code>dashboard</code>，将 <code>./data</code> 挂载到容器的 <code>/dashboard/data</code>。</li><li><strong>独立安装：</strong> 程序为该目录下的 <code>app</code>，服务名为 <code>nezha-dashboard</code>，由 systemd 或 OpenRC 管理。</li><li><strong>核心数据：</strong> <code>data/</code> 包含配置 <code>config.yaml</code>、默认数据库 <code>sqlite.db</code> 及其他运行数据。备份整个目录，不要只复制数据库主文件。</li></ul><p>下面按脚本默认路径操作。若你自定义了数据库、配置或 <code>tsdb.data_path</code>，或者使用外部挂载、符号链接，请另外备份对应的实际数据。反向代理配置、证书及 systemd/OpenRC 服务文件不在面板目录中，也需要另行保留。</p><div class="warning custom-block"><p class="custom-block-title">先迁移，再升级</p><p>本页用于兼容 V2 部署之间的迁移和恢复。建议先使用与源端相同的 Dashboard 版本恢复，再单独升级；一键安装脚本默认获取最新版，不能当作固定版本恢复工具。旧代际数据请先核对对应迁移说明，不要直接覆盖。</p></div><h2 id="_2-停止旧服务器上的-dashboard" tabindex="-1">2. 停止旧服务器上的 Dashboard <a class="header-anchor" href="#_2-停止旧服务器上的-dashboard" aria-label="Permalink to &quot;2. 停止旧服务器上的 Dashboard&quot;">​</a></h2><p><strong>只执行与你的部署方式对应的一组命令。</strong> 停止的是 Dashboard，不是各服务器的 Agent；迁移期间监控与告警会暂时不可用。</p><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span></code></pre></div><p>确认服务已停止。若安装的是独立的 Compose 命令，将示例中的 <code>docker compose</code> 换成 <code>docker-compose</code>。</p><h3 id="独立安装-systemd" tabindex="-1">独立安装：systemd <a class="header-anchor" href="#独立安装-systemd" aria-label="Permalink to &quot;独立安装：systemd&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span></code></pre></div><p>应显示 <code>inactive</code>；此时检查命令返回非零是正常的。</p><h3 id="独立安装-openrc" tabindex="-1">独立安装：OpenRC <a class="header-anchor" href="#独立安装-openrc" aria-label="Permalink to &quot;独立安装：OpenRC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>确认状态为已停止。若停止失败或日志显示异常退出，先排查，不要直接把运行中的目录打包当作一致性备份。</p><h2 id="_3-打包并保存备份" tabindex="-1">3. 打包并保存备份 <a class="header-anchor" href="#_3-打包并保存备份" aria-label="Permalink to &quot;3. 打包并保存备份&quot;">​</a></h2><p>以下示例在旧服务器创建备份；重复备份时换一个新文件名，避免覆盖旧包。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -czpf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span></span></code></pre></div><p>确认命令成功，并将备份与校验值保存到另一台机器或备份存储。通过受保护的传输方式复制，传输后再次计算校验值并比对。备份包含配置、数据库和凭据，不要放在公开下载目录。</p><ul><li><strong>仅做备份：</strong> 备份完成后，按第 5 节启动原 Dashboard。</li><li><strong>迁移服务器：</strong> 旧 Dashboard 保持停止，继续在新服务器恢复，避免两个面板同时执行任务和发送通知。</li></ul><h2 id="_4-恢复到目标服务器" tabindex="-1">4. 恢复到目标服务器 <a class="header-anchor" href="#_4-恢复到目标服务器" aria-label="Permalink to &quot;4. 恢复到目标服务器&quot;">​</a></h2><ol><li><strong>准备运行环境。</strong> 新服务器先准备 Docker/Compose，或适配目标 CPU 架构的独立程序与服务文件。可在空目录中参考<a href="/guide/dashboard.html">安装 Dashboard</a>建立部署，但恢复前须确认目标版本兼容并停止新面板。独立安装不能只复制目录就省略服务注册，也不要直接使用另一种 CPU 架构的 <code>app</code>。</li><li><strong>保留目标端原数据。</strong> 若目标已有数据，先停机并另做备份，将现有 <code>data/</code> 移至不冲突的备份位置。不要把两套数据库目录直接合并。</li><li><strong>解压到临时目录。</strong> 检查备份后，将其中的整个 <code>dashboard/data/</code> 恢复为目标 <code>/opt/nezha/dashboard/data/</code>，保留权限和所有权。保留目标环境适用的程序和服务文件；Docker 配置应核对镜像版本、端口和挂载，不要盲目用旧配置覆盖。</li><li><strong>检查外部依赖。</strong> 恢复单独备份的 TSDB 等外部数据，核对运行用户的读写权限、配置路径、反向代理、证书和防火墙。如果地址或端口改变，还需调整域名解析及 Agent 连接地址。</li></ol><div class="tip custom-block"><p class="custom-block-title">恢复后直接启动</p><p>不要在恢复数据后再次选择“安装面板端”或“修改面板配置”：当前脚本会重新生成并覆盖 <code>data/config.yaml</code>，Docker 部署还会重写 Compose 文件。使用下节命令启动即可。</p></div><h2 id="_5-启动并验证" tabindex="-1">5. 启动并验证 <a class="header-anchor" href="#_5-启动并验证" aria-label="Permalink to &quot;5. 启动并验证&quot;">​</a></h2><p>按部署方式选择一组命令。以下 Docker 命令启动已有容器，不拉取新镜像；若目标只有 Compose 文件、还没有容器，先确认其中镜像版本和挂载，再执行 <code>sudo docker compose -f /opt/nezha/dashboard/docker-compose.yaml up -d dashboard</code> 创建容器。</p><h3 id="docker-1" tabindex="-1">Docker <a class="header-anchor" href="#docker-1" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span></code></pre></div><h3 id="独立安装-systemd-1" tabindex="-1">独立安装：systemd <a class="header-anchor" href="#独立安装-systemd-1" aria-label="Permalink to &quot;独立安装：systemd&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>若手工新增或修改了 systemd 服务文件，启动前先执行 <code>sudo systemctl daemon-reload</code>。</p><h3 id="独立安装-openrc-1" tabindex="-1">独立安装：OpenRC <a class="header-anchor" href="#独立安装-openrc-1" aria-label="Permalink to &quot;独立安装：OpenRC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>恢复后检查：</p><ul><li>能用原账号登录，服务器清单、设置、告警和任务仍在。</li><li>Agent 能重新连接，状态与监控数据持续更新。</li><li>在线历史及已启用的 TSDB 历史数据符合备份时点。</li><li>日志没有数据库、权限或配置读取错误，域名和反向代理访问正常。</li></ul><p>验证完成前保留旧服务器和备份。需要回退时，先停止新 Dashboard，再切回原来的部署和连接地址；不要用旧程序直接打开已经由新版本迁移过的数据库。</p><h2 id="脚本依据" tabindex="-1">脚本依据 <a class="header-anchor" href="#脚本依据" aria-label="Permalink to &quot;脚本依据&quot;">​</a></h2><p>上述路径、服务名和菜单行为对应官方<a href="https://github.com/nezhahq/scripts/blob/main/install.sh" target="_blank" rel="noreferrer">中文安装脚本</a>、<a href="https://github.com/nezhahq/scripts/blob/main/extras/docker-compose.yaml" target="_blank" rel="noreferrer">Compose 模板</a>、<a href="https://github.com/nezhahq/scripts/blob/main/services/nezha-dashboard.service" target="_blank" rel="noreferrer">systemd 服务文件</a>和 <a href="https://github.com/nezhahq/scripts/blob/main/services/nezha-dashboard" target="_blank" rel="noreferrer">OpenRC 服务文件</a>。</p>`,41)])])}const F=a(h,[["render",n]]);export{c as __pageData,F as default};
